import { writeFile } from "node:fs/promises";

const resp = await fetch("{{BASE_URL}}/v1/images/generations", {
  method: "POST",
  headers: {
    "Authorization": "Bearer {{API_KEY}}",
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "{{MODEL}}",
    prompt: "一只在雪地里奔跑的柴犬，水彩风格",
  }),
  signal: AbortSignal.timeout(180_000),
});
const body = await resp.json();
if (!resp.ok) throw new Error(`${body.error.code}: ${body.error.message}`);
await writeFile("output.png", Buffer.from(body.data[0].b64_json, "base64"));

